entries.content:
{
  "status_block_type": "{{char}}的状态栏，用于记录{{char}}的状态",
  "statuses_list": [
    {
      "trigger": "阶段",
      "description": "《神女玄牝经》的修炼阶段",
      "values": [
        "神女玄牝经·第一卷·第一阶",
           ],
      "behavior": "《神女玄牝经》修炼阶段。由'定位'·'境界'组成，还没有修炼功法时阶段为'无'"
    },
   {
      "trigger": "称号",
      "description": "{{char}}目前表现相应的称号",
      "example": "仗义侠女",
      "behavior": "根据{{char}}当前的表现，给予一个符合{{char}}目前状态的称号。可以参考金庸等武侠小说作品。称号要有古白话风格，非口语化，要足够淫贱"
    },
    {
      "trigger": "行动",
      "description": "当前{{char}}的行为",
      "example": "修炼功法",
      "behavior": "在本轮对话中，{{char}}的所作所为"
    },
    {
      "trigger": "功法效果",
      "description": "{{char}}修炼《神女玄牝经》获得效果",
      "example": [
        "易筋伐髓（第三阶）-体质资质提升，身体敏感度柔韧度提升，性欲略微上升。",
        "神女玄牝-虽然《神女玄牝经》的部分修炼内容不合常理，让人质疑，但强大的功法效果让{{char}}选择相信这本神奇功法。({{char}}的某些常识似乎已经被改变，但是现在无疑是修炼功法更重要。)",
      ],
      "behavior": [
        "当上文中明确的赋予了{{char}}状态后,在状态添加对应的状态.添加新状态时注意使用<br>换行。",
        "状态的格式为：状态名称-状态描述（补充描述）；补充描述中可以进一步介绍状态，或者介绍状态的影响，由来等。具体的状态栏请根据剧情增加或更新。不要简写。",
        "除非在上下文中有明确的说明，否则不应突兀的增加，删除状态。新增状态应该为累加式，而非替换式。",
        "当状态栏中的条目过多时（超过十条），请对状态栏的条目进行总结和合并，在不改变原意的情况下缩减状态栏的总字数。保留原有格式。"
       "同一卷功法的各阶效果单独存在，三阶全部修炼完毕后整合进同一条目中。"
      ]
    },
    {
      "trigger": "服装",
      "description": "{{char}}当前各个部位的服装，以及服装的状态",
      "example": "头部-朴素银簪<br>颈部-无<br>手-无<br>上衣-白色袍服<br>下衣-白色长裤<br>内衣-红底金丝肚兜（被汗浸湿）<br>内裤-白绸亵裤<br>腿-白袜子<br>脚-乌皮六合靴（粘上少许泥土）<br>其他-身披鹤氅",
      "behavior": "填充Example中的部位，如果{{char}}服装发生变化，则可根据变化变动服装。使用<br>换行"
    },
{
      "trigger": "持有物",
      "description": "{{char}}当前持有的重要道具",
      "example": "银票（五百两），《神女玄牝经》（全本），随身宝剑",
      "behavior": "仅记录较为重要的道具，普通的物品不记录。当{{char}}丢失该道具时，删除对应的内容。"
    }
  ],
  "behavior": [
    "在回复的最后，记录与{{char}}相关的这些statuses。",
    "严格按Format输出。按StatusesList的要求和Trigger进行填充。",
    "数据只与{{char}}有关，随剧情变化随时且准确的更新。",
    "在回复的开始与结尾使用<char_statuses>包裹内容。",
    "不能使用```包裹状态栏，每项状态的末尾输出|进行分割；",
    "只能在永久性状态，临时状态，润滑/紧致度，服装这些状态中使用<br>换行，其他状态禁止换行"
  ],
  "format": "<char_statuses>阶段:|称号:|行动:|功法效果:|服装:|持有物:|</char_statuses>"
}
